"use client";

import { useEffect, useRef, type ReactNode, type ElementType, type CSSProperties } from "react";
import { track } from "@/lib/lead";
import { waLink } from "@/lib/site";
import { Icon } from "./Icon";

/** Responsive WebP from /public/media/img, pre-generated by the asset pipeline. */
export function Img({
  name,
  alt,
  sizes,
  widths = [640, 1280, 1920],
  w = 2504,
  h = 1409,
  priority,
  className,
  style,
}: {
  name: string;
  alt: string;
  sizes: string;
  widths?: number[];
  w?: number;
  h?: number;
  priority?: boolean;
  className?: string;
  style?: CSSProperties;
}) {
  const base = `/media/img/${name}`;
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src={`${base}-${widths[Math.min(1, widths.length - 1)]}.webp`}
      srcSet={widths.map((x) => `${base}-${x}.webp ${x}w`).join(", ")}
      sizes={sizes}
      alt={alt}
      width={w}
      height={h}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : undefined}
      decoding="async"
      className={className}
      style={style}
    />
  );
}

/** Fades/slides children in once they enter the viewport. */
export function Reveal({
  as: Tag = "div",
  delay = 0,
  className = "",
  children,
  ...rest
}: {
  as?: ElementType;
  delay?: number;
  className?: string;
  children: ReactNode;
} & Record<string, unknown>) {
  const ref = useRef<HTMLElement>(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) {
          el.classList.add("is-in");
          io.disconnect();
        }
      },
      { rootMargin: "0px 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return (
    <Tag ref={ref} className={`reveal ${className}`} style={{ "--d": `${delay}ms` } as CSSProperties} {...rest}>
      {children}
    </Tag>
  );
}

export function Eyebrow({ n, children, light }: { n?: string; children: ReactNode; light?: boolean }) {
  return (
    <p className={`eyebrow flex items-center gap-3 ${light ? "text-lime" : "text-olive-600"}`}>
      {n && <span className="font-display text-[0.95rem] tracking-normal normal-case italic">{n}</span>}
      <span className={`h-px w-8 ${light ? "bg-lime/60" : "bg-olive-600/50"}`} aria-hidden="true" />
      {children}
    </p>
  );
}

export function WhatsAppButton({
  where,
  className = "btn btn-ghost-light",
  label = "Falar no WhatsApp",
}: {
  where: string;
  className?: string;
  label?: string;
}) {
  return (
    <a
      href={waLink()}
      target="_blank"
      rel="noopener"
      className={className}
      onClick={() => track("whatsapp_click", { local: where })}
    >
      <Icon name="whatsapp" size={20} />
      {label}
    </a>
  );
}

export function PrimaryCta({ where, className = "btn btn-primary" }: { where: string; className?: string }) {
  return (
    <a href="#agendar" className={className} onClick={() => track("cta_click", { local: where })}>
      Quero conhecer as casas
      <Icon name="arrowRight" size={18} strokeWidth={2} />
    </a>
  );
}

export function openLeadModal(origem: string) {
  window.dispatchEvent(new CustomEvent("open-lead-modal", { detail: { origem } }));
}
